#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

banner "Meeting Ledger PostgreSQL on Windows"

# ── Example stage: replace with your real steps ───────────────────────────
stage "Preflight"
say "This setup keeps the application loopback-only. PostgreSQL durability does not make the preview safe to expose to colleagues."
step "Install or identify PostgreSQL 15+ and its client tools on this Windows host. Run this wizard from Git Bash or WSL after psql.exe and pg_dump.exe are on PATH."
step "Choose a Windows service account for PostgreSQL and a separate account for the Meeting Ledger server. Do not run either service as a local administrator."
if command -v psql.exe >/dev/null 2>&1 || command -v psql >/dev/null 2>&1; then
  note "Found a PostgreSQL client on PATH."
else
  warn "psql was not found on PATH. Complete the client-tool installation before the migration stage."
fi
pause "Complete the preflight and press Enter"

stage "TLS and network boundary"
say "Configure PostgreSQL for TLS before adding application credentials."
open_url "https://www.postgresql.org/docs/current/auth-pg-hba-conf.html"
step "Set ssl = on, install a certificate whose DNS name matches the database hostname, and restrict its private key to the PostgreSQL service account."
step "In pg_hba.conf, use hostssl with scram-sha-256 for only the Meeting Ledger server account and the loopback address while this prototype remains local-only."
step "Reload PostgreSQL and verify from a client that sslmode=verify-full succeeds. Do not use sslmode=disable or trust authentication."
pause "TLS and host access are restricted; press Enter"

stage "Database roles and schema owner"
say "Use a database bootstrap administrator only for this stage. Never put its connection string in .env or a scheduled task."
step "Follow the exact role and database SQL in docs/architecture/windows-postgres-operations.md: create ledger_owner and meeting_app, then create meeting_ledger owned by ledger_owner."
step "Use distinct long random passwords, retain them only in your approved secret store, and revoke PUBLIC access to the database."
step "Do not make meeting_app a superuser, table owner, or BYPASSRLS role. The server intentionally refuses those configurations."
pause "Roles and the empty database are ready; press Enter"

stage "Audio encryption key"
say "The key encrypts recording audio at rest. It is not a database password and must be backed up separately from every database backup."
step "Use the PowerShell command in docs/architecture/windows-postgres-operations.md to generate exactly 32 random bytes in a protected directory readable only by the Meeting Ledger service account."
ask MEETING_AUDIO_KEY_FILE "Paste the full Windows path to the protected 32-byte key file:"
if [[ -z "$MEETING_AUDIO_KEY_FILE" ]]; then
  warn "A key path is required. Stop now and rerun after creating the protected key file."
  exit 1
fi

stage "Migrate and configure the application"
say "Only the least-privilege application URL and key path are persisted to the Git-ignored .env file."
ask_secret DATABASE_URL "Paste the meeting_app DATABASE_URL with sslmode=verify-full:"
if [[ -z "$DATABASE_URL" ]]; then
  warn "DATABASE_URL is required. Stop now and rerun after creating the application credential."
  exit 1
fi
write_env DATABASE_URL "$DATABASE_URL"
write_env MEETING_AUDIO_KEY_FILE "$MEETING_AUDIO_KEY_FILE"
ask_secret DATABASE_ADMIN_URL "Paste the one-time ledger_owner DATABASE_ADMIN_URL with sslmode=verify-full:"
if [[ -z "$DATABASE_ADMIN_URL" ]]; then
  warn "DATABASE_ADMIN_URL is required to apply migrations, but it has not been written to .env. Re-run when ready."
  exit 1
fi
if confirm "Apply migrations now with ledger_owner"; then
  DATABASE_ADMIN_URL="$DATABASE_ADMIN_URL" MEETING_DB_APP_ROLE=meeting_app npm.cmd run db:migrate
  unset DATABASE_ADMIN_URL
else
  warn "Skipped migration. Before starting the server, run: DATABASE_ADMIN_URL=<ledger_owner URL> MEETING_DB_APP_ROLE=meeting_app npm.cmd run db:migrate"
fi

stage "Backup, restore, monitoring, and rotation boundary"
say "Schedule scripts/backup-windows-postgres.ps1 under a dedicated backup identity with a protected pgpass.conf file and an encrypted destination."
step "Perform a restore drill into a fresh database before recording real meetings. Verify the audit chain as an authorized audit reader and re-run retention/deletion reconciliation before serving the restored database."
step "Configure alerts for backup failure, failed restore verification, low disk, TLS failure, connection saturation, replication lag if added, and audit-integrity failure."
step "Do not replace the active audio key file. The current application supports one active key and has no re-encryption migration; follow the documented maintenance boundary instead."
pause "Operating controls are scheduled and reviewed; press Enter"

finish
: <<'LEGACY_TEMPLATE_EXAMPLE'
say "We'll grab your Stripe test keys and store them for local dev + CI."
open_url "https://dashboard.stripe.com/test/apikeys"
step "On the API keys page, copy the Publishable key (starts pk_test_)."
ask STRIPE_PUBLISHABLE_KEY "Paste the publishable key:"
step "Click 'Reveal test key' on the Secret key row, then copy it."
ask_secret STRIPE_SECRET_KEY "Paste the secret key:"
write_env STRIPE_PUBLISHABLE_KEY "$STRIPE_PUBLISHABLE_KEY"
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
set_secret STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"   # CI needs this one
# ──────────────────────────────────────────────────────────────────────────

finish
LEGACY_TEMPLATE_EXAMPLE
